"""Inspect sealed rounds, intent failures and actual saved-GPX effects without hiding history."""
import argparse
import collections
import hashlib
import json
from pathlib import Path


def read(path,default=None):
    return json.loads(path.read_text()) if path.is_file() else default


def generate(corpus):
    corpus=Path(corpus).resolve();rounds=[]
    roots=sorted((corpus/'rounds').iterdir())
    for extra in ['edge-courses','normalized-subsets','frozen-history','legacy-regression','fresh-courses','fresh-valid-courses']:
        if (corpus/extra/'rounds').exists():roots.extend(sorted((corpus/extra/'rounds').iterdir()))
    for root in roots:
        catalog=read(root/'catalog.json')
        if catalog is None:continue
        states={mode:read(root/(mode+'-status.json'),{}) for mode in ['model','oracle']}
        if root.name in {'candidate-v6','reserved-projects-v6','saved-luna-v4-final-v11','recovered-luna-v12'} and not states['oracle']:
            reference=corpus/'rounds/final-native-v11'
            reference_state=read(reference/'oracle-status.json',{})
            matched={}
            for case in catalog:
                row=reference_state.get('results',{}).get(case['id'])
                file=root/'inputs'/(case['project']+'.gpx');other=reference/'inputs'/file.name
                if row and row.get('case_sha256')==hashlib.sha256(json.dumps(case,sort_keys=True).encode()).hexdigest() and other.is_file() and hashlib.sha256(file.read_bytes()).hexdigest()==hashlib.sha256(other.read_bytes()).hexdigest():
                    matched[case['id']]={**row,'reference_round':reference.name}
            if matched:
                states['oracle']={**reference_state,'results':matched,'denominator':sum(c['expectation']=='execute' for c in catalog),'selected_cases':list(matched),'counts':dict(collections.Counter(v['status'] for v in matched.values())),'reference_round':reference.name}
        cases=[]
        for case in catalog:
            value={k:case.get(k) for k in ['id','project','category','scenario','request','expectation','partition','previous_case','oracle_reason']}
            figure=root/'figures'/(case['id']+'.png')
            value['figure']=figure.relative_to(corpus).as_posix() if figure.is_file() else None
            for mode,state in states.items():
                record=state.get('results',{}).get(case['id'],{}).copy()
                record['current']=bool(record) and record.get('source_sha256')==state.get('current_code')
                directory=record.get('artifact_directory')
                if directory:
                    work=Path(directory)
                    if work.is_relative_to(corpus):
                        record['links']={n:(work/n).relative_to(corpus).as_posix() for n in ['planning.json','planning-error.json','plan.json','previous-model-plan.json','result.json','refined.execution.json','refined.gpx','native.log','source-planning.json','replay-provenance.json','refined.failure.json'] if (work/n).is_file()}
                value[mode]=record
            cases.append(value)
        seal=read(root/'input-seal.json',{});failures=[n for n,sha in seal.items() if not (root/n).is_file() or hashlib.sha256((root/n).read_bytes()).hexdigest()!=sha]
        rounds.append({'name':root.relative_to(corpus).as_posix().removeprefix('rounds/'),'cases':cases,'catalog_cases':len(cases),'executable_cases':sum(c['expectation']=='execute' for c in catalog),
                       'states':{mode:{k:state.get(k) for k in ['counts','denominator','selected_cases','current_code','image_id','updated_unix','mode','model_calls_this_round','source_round','source_model_code']} for mode,state in states.items()},
                       'input_seal':{'files':len(seal),'failed':failures},'post_audit':read(root/'saved-gpx-post-audit.json',{}),
                       'runtime':read(root/'execution-environment.json',{}),'superseded':read(root/'superseded.json',{})})
    result={'window':read(corpus/'run-window.json',{}),'progress':read(corpus/'progress.json',{}),'rounds':rounds,
            'inventory':read(corpus/'inventory.json',[]),'intake_edges':read(corpus/'intake-edge-results.json',[]),
            'fresh_intake':read(corpus/'fresh-project-results-after-link-gate.json',[]),'covariance_audit':read(corpus/'covariance-independent-audit.json',{}),'container_timeout':read(corpus/'container-timeout-audit.json',{}),'metamorphic_audit':read(corpus/'reuse-tests/metamorphic-audit.json',{}),'final_review':read(corpus/'final-review.json',{}),'showcases':read(corpus/'showcase-figures.json',[])}
    (corpus/'challenge-review.json').write_text(json.dumps(result,indent=2)+'\n')
    (corpus/'validation-report.html').write_text(HTML)
    print(json.dumps({'rounds':len(rounds),'sealed_input_failures':sum(len(r['input_seal']['failed']) for r in rounds)}))


HTML='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RADAR-PD · Advanced refinement validation</title>
<style>:root{font:15px/1.5 system-ui;color:#163d32;background:#f3f6f4}*{box-sizing:border-box}body{margin:0}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}h2{font-size:20px;margin:0 0 10px}h3{font-size:16px}.card{padding:20px;background:white;border:1px solid #ceded4;border-radius:8px;margin:18px 0}.muted{color:#64776c}.stats{display:flex;gap:12px;flex-wrap:wrap}.stat{background:#edf4ef;border-radius:5px;padding:12px 18px;flex:1;min-width:140px}.stat b{font-size:25px;display:block}input,select,button{font:inherit;padding:8px;border:1px solid #a5bdac;border-radius:5px;background:white;color:inherit}button{cursor:pointer}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0}table{width:100%;border-collapse:collapse;font-size:13px}td,th{border-bottom:1px solid #dde6df;text-align:left;padding:10px;vertical-align:top}th{background:#f4f7f5;color:#60746a}tr[data-id]{cursor:pointer}tr[data-id]:hover{background:#eff6f1}.scroll{overflow:auto}.badge{display:inline-block;border-radius:4px;padding:3px 6px;background:#e9edf0;white-space:nowrap}.verified_execution,.correctly_blocked{background:#dff1e5;color:#195e36}.scientific_stop{background:#fff0d7;color:#8a5c13}.semantic_mismatch,.runtime_defect,.provider_blocked,.planner_validation_failure{background:#ffe7df;color:#9c3c25}.note{padding:12px 16px;background:#f5f7f5;border-left:3px solid #799a86}a{color:#246847}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace;background:#f6f8f6;padding:14px;max-height:450px;overflow:auto}dialog{width:min(1300px,95vw);max-height:92vh;border:1px solid #b3c6ba;border-radius:8px;padding:22px}dialog::backdrop{background:#163d3266}.close{float:right}.links{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0}details{margin:12px 0}summary{cursor:pointer}.number{font-variant-numeric:tabular-nums}img{max-width:100%}@media(max-width:700px){main{padding:12px}.card{padding:14px}h1{font-size:23px}}</style>
<main><p class="muted">RADAR-PD · GSAS-II RECIPE VALIDATION</p><h1>Advanced refinement, checked against saved GPXs</h1><p class="muted" id="window"></p><p class="note">Luna plans typed operations at reasoning <b>none</b>. The compiled Python wrapper uses trusted GSAS-II operations. Accepted plans pass native preflight and compiled execution on a separate GPX; completed outputs are reloaded for independent checks. An executed recipe is still subject to scientific judgment; bound and identifiability stops are not counted as completed refinements.</p>
<div class="card"><h2>Current checked results</h2><div class="stats" id="finalstats"></div><p id="finalscope" class="muted"></p><p id="modelaccess" class="note"></p><p><a href="http://127.0.0.1:8897/">Open the local refinement planner</a> · <a href="final-review.json">Full final review</a> · <a href="wheel-release-isolated/verification.json">Isolated Linux wheel execution</a> · <a href="streaming-real-scans/independent-saved-gpx-audit.json">Real scan arrival audit</a></p><details><summary>What changed and what remains outside scope</summary><div id="findings"></div><ul id="limits"></ul></details></div>
<div class="card"><h2>Actual saved-project examples</h2><p class="muted">Compiled scripts were executed on these projects. Full patterns and peak details show observed data, calculation, residuals and phase Bragg ticks. These are execution examples, not evidence that every phase or model is correct. The NOMAD test deliberately holds NMC at its near-zero starting contribution; normalized HAP scales are not weight percentages.</p><div id="showcases"></div><p><a href="ui-nomad-final-immutable/independent-final-gpx-audit.json">Final NOMAD immutable audit</a> · <a href="data-fault-controls/results.json">Damaged-input controls</a> · <a href="independent-audit-implicit-save-incident.json">Audit-reader isolation incident</a></p></div><div class="card"><div class="controls"><label>Evidence set <select id="round"></select></label><button id="refresh">Refresh results</button></div><div class="stats" id="stats"></div><p id="coverage" class="muted"></p><details><summary>Coverage and integrity</summary><p id="integrity"></p><p id="intake"></p><p>Earlier failures remain available in their original rounds. Revisions in the natural-language suite use the actual previous model reply; an oracle plan is never substituted. The reserved project partition is separate from development. Controlled history fixtures are labeled separately from original experimental projects.</p></details></div>
<div class="card"><div class="controls"><input id="search" placeholder="Find sample, operation or case" aria-label="Find case"><select id="outcome" aria-label="Model outcome"><option value="">All model outcomes</option></select><select id="category" aria-label="Recipe category"><option value="">All operations</option></select></div><div class="scroll"><table><thead><tr><th>Case</th><th>Requested course</th><th>Project</th><th>Native reference</th><th id="modelhead">Luna result</th><th>Calls</th></tr></thead><tbody id="rows"></tbody></table></div></div><p class="muted"><a href="challenge-review.json">Full review data</a> · <a href="catalog.json">Corpus catalog</a> · <a href="progress.json">Work status</a></p></main>
<dialog id="detail"><button class="close" onclick="this.parentNode.close()">Close</button><h2 id="title"></h2><p id="caseinfo" class="muted"></p><pre id="request"></pre><p id="problem" class="note" hidden></p><div id="links" class="links"></div><div id="effects"></div><details><summary>Plan or source proposal</summary><pre id="plan"></pre></details><details><summary>Native independent audit</summary><pre id="audit"></pre></details><div id="figure"></div></dialog>
<script>
const $=x=>document.getElementById(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),label=x=>String(x||'pending').replaceAll('_',' ');let data={},selected=null,serial=0;
const friendly=x=>({'source_clarification_not_reexecuted':'Source clarification · not reexecuted','prior_error_not_replayed':'Prior error · not executed','deferred_provider':'Deferred · provider unavailable'}[x]||label(x));
const badge=x=>`<span class="badge ${esc(x||'pending')}">${esc(friendly(x))}</span>`;
const number=x=>typeof x==='number'?Number(x).toPrecision(7):'—';
async function load(){const old=$('round').value;data=await(await fetch('challenge-review.json?ts='+Date.now())).json();const preferred=['recovered-luna-v12','saved-luna-v4-final-v11','final-native-v11','candidate-v6','candidate-v4'];const ordered=[...preferred.map(n=>data.rounds.find(r=>r.name===n)).filter(Boolean),...data.rounds.filter(r=>!preferred.includes(r.name))];const titles={'recovered-luna-v12':'Fresh current Luna generation · service recovered','saved-luna-v4-final-v11':'Current worker · saved Luna plans · zero new calls','final-native-v11':'Current worker · executable reference recipes','candidate-v6':'Latest live Luna sweep · interrupted by service','candidate-v4':'Earlier complete live Luna generation'};$('round').innerHTML=ordered.map(r=>`<option value="${esc(r.name)}">${esc(titles[r.name]||r.name)}</option>`).join('');$('round').value=data.rounds.some(r=>r.name===old)?old:(data.rounds.some(r=>r.name==='recovered-luna-v12')?'recovered-luna-v12':data.rounds.some(r=>r.name==='saved-luna-v4-final-v11')?'saved-luna-v4-final-v11':data.rounds.at(-1)?.name);$('window').textContent='Authorized work window: '+data.window.started_utc+' to '+data.window.deadline_utc+'. '+(data.final_review?.work_status||'Results are checkpointed while the campaign runs.');finalOverview();choose();}
function finalOverview(){$('showcases').innerHTML=(data.showcases||[]).map(x=>`<details><summary>${esc(x.title)}</summary><p><a href="${esc(x.gpx)}">Saved GPX</a> · <a href="${esc(x.path)}">Open full figure</a></p><img loading="lazy" alt="${esc(x.title)}" src="${esc(x.path)}"></details>`).join('');const f=data.final_review||{},n=f.native_reference?.counts||{},p=f.independent_saved_gpx_audit||{};$('finalstats').innerHTML=[[f.software_tests||0,'Software tests passed'],[n.verified_execution||0,'Verified reference executions'],[n.scientific_stop||0,'Scientific stops'],[n.runtime_defect||0,'Reference execution defects'],[p.checks||0,'Additional saved-GPX checks']].map(([v,t])=>`<div class="stat"><b>${v}</b>${esc(t)}</div>`).join('');$('finalscope').textContent=`Reference denominator ${f.native_reference?.requests??'pending'} executable recipes. ${p.outputs??0} completed reference/replay outputs reloaded; ${p.failures?.length??0} independent audit failures. These are outputs and recipes, not independent experiments.`;const m=f.catalog_access||f.model_access||{};$('modelaccess').textContent=`Last recorded Luna catalog check: ${m.checked_utc||'not recorded'} · HTTP ${m.status||m.http_status||'unknown'}. Earlier generation was interrupted by HTTP 403. Fresh current run: ${Object.entries(f.fresh_luna_generation?.counts||{}).map(([k,v])=>v+' '+label(k)).join(', ')||'awaiting outcomes'}; ${f.fresh_luna_generation?.recorded_outcomes??0} of ${f.fresh_luna_generation?.denominator??205} requests recorded. Saved-plan replay results are separate and make zero new model calls.`;$('findings').innerHTML=(f.fixes||[]).map(x=>`<p><b>${esc(x.problem)}</b><br>${esc(x.result)}</p>`).join('');$('limits').innerHTML=(f.limits||[]).map(x=>'<li>'+esc(x)+'</li>').join('');}
function choose(){selected=data.rounds.find(r=>r.name===$('round').value);$('outcome').innerHTML='<option value="">All model outcomes</option>'+[...new Set(selected.cases.map(c=>c.model.status||'pending'))].sort().map(s=>`<option value="${esc(s)}">${esc(label(s))}</option>`).join('');$('category').innerHTML='<option value="">All operations</option>'+[...new Set(selected.cases.map(c=>c.category))].sort().map(s=>`<option value="${esc(s)}">${esc(label(s))}</option>`).join('');render();}
function render(){if(!selected)return;const m=selected.states.model||{},n=selected.states.oracle||{},counts=m.counts||{},replay=m.mode==='saved_model_plan_replay',done=Object.values(counts).reduce((a,b)=>a+b,0);$('modelhead').textContent=replay?'Saved-plan replay':'Luna result';$('stats').innerHTML=[[selected.catalog_cases,'Cases in this round'],[done,replay?'Replay outcomes recorded':'Model outcomes recorded'],[counts.verified_execution||0,'Verified native executions'],[counts.scientific_stop||0,'Scientific stops'],[replay?(counts.source_clarification_not_reexecuted||0):(counts.correctly_blocked||0),replay?'Source clarifications':'Correctly blocked'],[replay?((counts.prior_error_not_replayed||0)+(counts.contract_mismatch_not_replayed||0)):((counts.semantic_mismatch||0)+(counts.planner_validation_failure||0)),replay?'Prior errors · not executed':'Intent / validation errors']].map(([v,t])=>`<div class="stat"><b>${v}</b>${esc(t)}</div>`).join('');$('coverage').textContent='Model denominator '+(m.denominator??'not started')+'; selected '+(m.selected_cases?.length??0)+'. Native reference: '+Object.entries(n.counts||{}).map(([k,v])=>v+' '+label(k)).join(', ')+'. '+(m.current_code?'Model code '+m.current_code.slice(0,12)+'. ':'')+'Any pending cases remain in the table.'+(replay?' This is a current-worker replay of earlier genuine proposals; no new model calls. Source clarifications and prior errors are not passed executions.':'')+(selected.superseded.reason?' Superseded: '+selected.superseded.reason:'');$('integrity').textContent=selected.input_seal.files+' sealed files checked; '+selected.input_seal.failed.length+' input hash failures. Post-audit: '+(selected.post_audit.checks??0)+' independent saved-GPX checks, '+(selected.post_audit.failures?.length??0)+' failures. Image '+(selected.runtime.image_id||'not captured yet')+'.';$('intake').textContent=data.inventory.length+' main corpus projects; '+data.inventory.filter(x=>x.status==='inspected').length+' inspected for recipe execution. Additional intake projects: '+data.intake_edges.map(x=>x.id+' ('+label(x.status)+')').join('; ')+'.';const text=$('search').value.toLowerCase();$('rows').innerHTML=selected.cases.filter(c=>(!$('outcome').value||(c.model.status||'pending')===$('outcome').value)&&(!$('category').value||c.category===$('category').value)&&(!text||JSON.stringify(c).toLowerCase().includes(text))).map(c=>`<tr data-id="${esc(c.id)}"><td>${esc(c.id)}</td><td><b>${esc(c.scenario)}</b><br>${esc(label(c.category))}</td><td>${esc(c.project)}</td><td>${c.expectation==='needs_input'?'Clarification expected':badge(c.oracle.status)+(c.oracle.reference_round?'<br><span class="muted">Current engine reference</span>':'')}</td><td>${badge(c.model.status)}</td><td>${c.model.planning?.calls??'—'}</td></tr>`).join('');document.querySelectorAll('tr[data-id]').forEach(r=>r.onclick=()=>show(r.dataset.id));}
async function get(path){return (await fetch(path)).json();}
async function show(id){const token=++serial,c=selected.cases.find(c=>c.id===id),record=c.model.status?c.model:c.oracle,links=record.links||{};$('title').textContent=c.id+' · '+c.scenario;$('caseinfo').textContent=c.project+' · '+selected.name+' · '+label(record.status);$('request').textContent=c.request;$('problem').hidden=!(record.error||c.oracle_reason);$('problem').textContent=[record.error,c.oracle_reason].filter(Boolean).join(' ');$('links').innerHTML=Object.entries(links).map(([n,p])=>`<a href="${esc(p)}">${esc(n)}</a>`).join('');$('plan').textContent='No accepted plan';$('effects').innerHTML='';$('audit').textContent=JSON.stringify(record,null,2);$('figure').innerHTML='';$('detail').showModal();if(links['plan.json']){const plan=await get(links['plan.json']);if(token!==serial)return;$('plan').textContent=JSON.stringify(plan,null,2)}if(links['result.json']){const audit=await get(links['result.json']);if(token!==serial)return;$('audit').textContent=JSON.stringify(audit,null,2)}if(links['refined.execution.json']){const receipt=await get(links['refined.execution.json']);if(token!==serial)return;$('effects').innerHTML='<h3>Actual stage effects</h3>'+receipt.stages.map((s,i)=>{const p=s.parameter_changes||{};return `<details ${i===0?'open':''}><summary><b>${i+1}. ${esc(s.title)}</b> · ${esc(label(s.status))} · ${p.released_parameters_changed??0} released parameters changed · ${p.fixed_parameters_checked??0} fixed parameters checked</summary><p>Rwp: ${esc(Object.entries(s.rwp||{}).map(([h,v])=>h+' '+number(v)+'%').join('; '))}. Independent variables: ${s.actual_vary?.length??'not executed'}. Unexpected fixed-value changes: ${p.unexpected_fixed_changes?.length??'not audited'}.</p><div class="scroll"><table><thead><tr><th>Native variable</th><th>Before</th><th>After</th><th>Change</th><th>Conditional s.u.</th></tr></thead><tbody>${(p.released_parameters||[]).map(v=>`<tr><td>${esc(v.location||v.variable)}<br><span class="muted">${esc(v.group==='phase_fraction'&&v.family==='Scale'?'HAP phase scale (not weight fraction)':v.meaning||'')} · ${esc(v.variable)}</span>${v.changed?'':' · unchanged'}</td><td class="number">${number(v.before)}</td><td class="number">${number(v.after)}</td><td class="number">${number(v.delta)}</td><td class="number">${number(v.sigma)}</td></tr>`).join('')}</tbody></table></div></details>`}).join('')}if(c.figure)$('figure').innerHTML='<h3>Native final pattern with phase Bragg ticks</h3><img alt="Native GSAS-II observed and calculated pattern with residuals and phase ticks" src="'+esc(c.figure)+'">';}
$('round').onchange=choose;$('refresh').onclick=load;for(const x of ['search','outcome','category'])$(x).addEventListener(x==='search'?'input':'change',render);load().catch(e=>$('coverage').textContent=e.message);
</script></html>'''


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('corpus');a=p.parse_args();generate(a.corpus)
